-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

CREATE OR REPLACE FUNCTION public.message_after_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if old.conversation_id is null then
    return old;
  end if;

  if old.read_at is null and old.kind = 'message' then
    update public.conversation_unreads
    set unread_count = greatest(unread_count - 1, 0)
    where conversation_id = old.conversation_id
      and user_id = old.recipient_id;
  end if;

  update public.conversations c
  set last_message_id = latest.id,
      last_message_at = latest.created_at,
      last_message_preview = latest.preview
  from (
    select null::uuid as id, null::timestamptz as created_at, null::text as preview
    where not exists (select 1 from public.messages where conversation_id = old.conversation_id)
    union all
    (select m.id, m.created_at,
            left(case when char_length(btrim(m.body)) = 0 then 'Photo' else m.body end, 140)
     from public.messages m
     where m.conversation_id = old.conversation_id
     order by m.created_at desc, m.id desc
     limit 1)
  ) latest
  where c.id = old.conversation_id
    and c.last_message_id = old.id;

  return old;
end;
$function$;

grant execute on function public.message_after_delete() to anon;
grant execute on function public.message_after_delete() to authenticated;
grant execute on function public.message_after_delete() to public;
grant execute on function public.message_after_delete() to service_role;
